        Request request = requestRepository.findById(requestId).orElseThrow(() -> new IllegalArgumentException("Request not found"));
        if (!request.getRequester().getId().equals(userId)) {
            throw new IllegalArgumentException("Only requester can submit");
        }
        if (request.getStatus() != RequestStatus.DRAFT) {
            throw new IllegalArgumentException("Request already submitted");
        }
        // Validate mandatory fields
        validateRequest(request);
        // Generate workflow
        List<ApprovalStep> steps = generateWorkflow(request);
        approvalStepRepository.saveAll(steps);
        request.setStatus(RequestStatus.SUBMITTED);
        request = requestRepository.save(request);
        auditLogRepository.save(new AuditLog(request, request.getRequester(), AuditAction.SUBMIT, "Request submitted"));
        return request;
    }

    private void validateRequest(Request request) {
        switch (request.getType()) {
            case EXPENSE:
                if (request.getAmount() == null) throw new IllegalArgumentException("Amount required for expense");
                break;
            case LEAVE:
                if (request.getStartDate() == null || request.getEndDate() == null) throw new IllegalArgumentException("Dates required for leave");
                break;
            // ACCESS and ASSET may have optional fields
        }
    }

    private List<ApprovalStep> generateWorkflow(Request request) {
        List<ApprovalStep> steps = new ArrayList<>();
        User requester = request.getRequester();
        User manager = requester.getManager();

        int step = 1;

        // If requester has a manager, add manager approval
        if (manager != null) {
            steps.add(new ApprovalStep(request, step++, manager));
        } else if (requester.getRole() == Role.MANAGER) {
            // For managers without managers, assign to admin or finance based on request type
            admin = findUserByRole(Role.ADMIN);
            steps.add(new ApprovalStep(request, step++, admin));
        } else {
            // For other roles without managers, this shouldn't happen but handle gracefully
            throw new IllegalArgumentException("Requester has no manager and is not a manager role");
        }

        User finance = null;
        admin = null;

        switch (request.getType()) {
            case LEAVE:
                // Manager approval already added above
                break;
            case EXPENSE:
                if (request.getAmount().compareTo(BigDecimal.valueOf(50000)) > 0) {
                    // Manager -> Finance (if not already added)
                    finance = findUserByRole(Role.FINANCE);
                    if (!steps.stream().anyMatch(s -> s.getApprover().equals(finance))) {
                        steps.add(new ApprovalStep(request, step++, finance));
                    }
                }
                break;
            case ACCESS:
                // Manager -> Admin (if not already added)
                admin = findUserByRole(Role.ADMIN);
                if (!steps.stream().anyMatch(s -> s.getApprover().equals(admin))) {
                    steps.add(new ApprovalStep(request, step++, admin));
                }
                break;
            case ASSET:
                if (request.getAmount().compareTo(BigDecimal.valueOf(100000)) > 0) {
                    // Manager -> Finance -> Admin
                    finance = findUserByRole(Role.FINANCE);
                    if (!steps.stream().anyMatch(s -> s.getApprover().equals(finance))) {
                        steps.add(new ApprovalStep(request, step++, finance));
                    }
                    admin = findUserByRole(Role.ADMIN);
                    if (!steps.stream().anyMatch(s -> s.getApprover().equals(admin))) {
                        steps.add(new ApprovalStep(request, step++, admin));
                    }
                }
                break;
        }
        return steps;
    }

    private User findUserByRole(Role role) {
        // For simplicity, find first user with role.
        return userRepository.findAll().stream().filter(u -> u.getRole() == role).findFirst().orElseThrow(() -> new IllegalArgumentException("No user with role " + role));
    }

    @Transactional
    public void approveStep(Long requestId, Long userId, String comments) {
        ApprovalStep step = approvalStepRepository.findByRequestIdAndStepOrder(requestId, getCurrentStepOrder(requestId))
                .orElseThrow(() -> new IllegalArgumentException("No pending step"));
        if (!step.getApprover().getId().equals(userId)) {
            throw new IllegalArgumentException("Not assigned approver");
        }
        step.setStatus(ApprovalStatus.APPROVED);
        step.setComments(comments);
        step.setApprovedAt(java.time.LocalDateTime.now());
        approvalStepRepository.save(step);
        auditLogRepository.save(new AuditLog(step.getRequest(), step.getApprover(), AuditAction.APPROVE, "Step approved: " + comments));

        // Check if final
        List<ApprovalStep> allSteps = approvalStepRepository.findByRequestIdOrderByStepOrder(requestId);
        boolean allApproved = allSteps.stream().allMatch(s -> s.getStatus() == ApprovalStatus.APPROVED);
        if (allApproved) {
            Request request = step.getRequest();
            request.setStatus(RequestStatus.APPROVED);
            requestRepository.save(request);
            auditLogRepository.save(new AuditLog(request, step.getApprover(), AuditAction.APPROVE, "Request fully approved"));
        }
    }

    @Transactional
    public void rejectStep(Long requestId, Long userId, String comments) {
        ApprovalStep step = approvalStepRepository.findByRequestIdAndStepOrder(requestId, getCurrentStepOrder(requestId))
                .orElseThrow(() -> new IllegalArgumentException("No pending step"));
        if (!step.getApprover().getId().equals(userId)) {
            throw new IllegalArgumentException("Not assigned approver");
        }
        step.setStatus(ApprovalStatus.REJECTED);
        step.setComments(comments);
        step.setApprovedAt(java.time.LocalDateTime.now());
        approvalStepRepository.save(step);
        Request request = step.getRequest();
        request.setStatus(RequestStatus.REJECTED);
        requestRepository.save(request);
        auditLogRepository.save(new AuditLog(request, step.getApprover(), AuditAction.REJECT, "Request rejected: " + comments));
    }

    @Transactional
    public void cancelRequest(Long requestId, Long userId) {
        Request request = requestRepository.findById(requestId).orElseThrow(() -> new IllegalArgumentException("Request not found"));
        if (!request.getRequester().getId().equals(userId)) {
            throw new IllegalArgumentException("Only requester can cancel");
        }
        if (request.getStatus() == RequestStatus.APPROVED || request.getStatus() == RequestStatus.REJECTED) {
            throw new IllegalArgumentException("Cannot cancel finalized request");
        }
        request.setStatus(RequestStatus.CANCELLED);
        requestRepository.save(request);
        auditLogRepository.save(new AuditLog(request, request.getRequester(), AuditAction.CANCEL, "Request cancelled"));
    }

    private Integer getCurrentStepOrder(Long requestId) {
        List<ApprovalStep> steps = approvalStepRepository.findByRequestIdOrderByStepOrder(requestId);
        for (ApprovalStep step : steps) {
            if (step.getStatus() == ApprovalStatus.PENDING) {
                return step.getStepOrder();
            }
        }
        return null; // All done
    }

    public List<Request> getRequestsByUser(Long userId) {
        return requestRepository.findByRequesterIdAndStatus(userId, RequestStatus.DRAFT); // Adjust
    }

    public List<ApprovalStep> getPendingApprovals(Long userId) {
        return approvalStepRepository.findByApproverIdAndStatus(userId, ApprovalStatus.PENDING);
    }
}
